import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 실행예산액은 품의서의 프로젝트·예산과목 본예산에 딸린 exec_budget.amount 합계
// 가정: 집행액은 품의서 예산과목의 commitment.amount 합계
// 가정: 이월예산액은 품의서의 프로젝트·예산과목 budget_carryover.carryover_amount 합계
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const BASE_SELECT = `
  SELECT
    pr.purchase_request_id AS "purchaseRequestId",
    pr.title AS "title",
    pr.project_id AS "projectId",
    pr.budget_item_id AS "budgetItemId",
    COALESCE((
      SELECT SUM(e.amount)
      FROM exec_budget e
      JOIN main_budget m ON m.main_budget_id = e.main_budget_id
      WHERE m.project_id = pr.project_id
        AND m.budget_item_id = pr.budget_item_id
    ), 0) AS "execBudgetAmount",
    COALESCE((
      SELECT SUM(c.carryover_amount)
      FROM budget_carryover c
      WHERE c.project_id = pr.project_id
        AND c.budget_item_id = pr.budget_item_id
    ), 0) AS "carryoverAmount",
    COALESCE((
      SELECT SUM(cm.amount)
      FROM commitment cm
      WHERE cm.budget_item_id = pr.budget_item_id
    ), 0) AS "executedAmount"
  FROM purchase_request pr
`;

const OUTER_SELECT = `
  SELECT
    b."purchaseRequestId",
    b."title",
    b."budgetItemId",
    b."execBudgetAmount",
    b."carryoverAmount",
    b."execBudgetAmount" + b."carryoverAmount" AS "totalBudgetAmount",
    b."executedAmount",
    b."execBudgetAmount" + b."carryoverAmount" - b."executedAmount" AS "budgetBalance"
`;

function optionalId(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

function optionalInt(value: unknown, label: string, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const text = String(value);
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr02402Controller {
  @Get('/purchase-requests/budget-status')
  async listPurchaseRequestBudgetStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const projectId = optionalId(query['projectId'], '프로젝트');
    const budgetItemId = optionalId(query['budgetItemId'], '예산과목');
    const titleRaw = query['title'];
    const title = titleRaw === undefined || titleRaw === null || titleRaw === '' ? null : String(titleRaw);
    const page = optionalInt(query['page'], 'page', 0);
    const size = Math.min(optionalInt(query['size'], 'size', DEFAULT_SIZE), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상이어야 합니다.');
    }
    return transaction(async (db) => {
      const where = `
        WHERE (CAST(:projectId AS bigint) IS NULL OR pr.project_id = CAST(:projectId AS bigint))
          AND (CAST(:budgetItemId AS bigint) IS NULL OR pr.budget_item_id = CAST(:budgetItemId AS bigint))
          AND (CAST(:title AS text) IS NULL OR pr.title LIKE '%' || CAST(:title AS text) || '%')
      `;
      const filterParams = { projectId, budgetItemId, title };
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM purchase_request pr ' + where,
        filterParams,
      );
      const total = Number(countRows[0]['total']);
      const items = await db.query(
        OUTER_SELECT + ' FROM (' + BASE_SELECT + where + ') b ORDER BY b."purchaseRequestId" DESC LIMIT :size OFFSET :offset',
        { ...filterParams, size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }

  @Get('/purchase-requests/:purchaseRequestId/budget-status')
  async getPurchaseRequestBudgetStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const idText = req.params['purchaseRequestId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의서 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        OUTER_SELECT + ' FROM (' + BASE_SELECT + ' WHERE pr.purchase_request_id = CAST(:id AS bigint)) b',
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

