import { useState } from 'react';
import type { PageProps, Row, Page } from '../kit';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';

const SIZE = 20;

function Detail({ id, role, onClose }: { id: number; role: string; onClose: () => void }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', '/purchase-requests/' + id + '/budget-status', role),
    [id],
  );
  return (
    <Drawer title={'구매품의서 예산 현황'} onClose={onClose}>
      {loading && <p>불러오는 중…</p>}
      {error && <ErrorText text={error} />}
      {data && (
        <Pairs
          items={[
            ['품의서 ID', String(data.purchaseRequestId)],
            ['예산과목', <RefName table={'budget_item'} role={role} value={data.budgetItemId} />],
            ['실행예산액', <Num value={data.execBudgetAmount} />],
            ['이월 대상 금액', <Num value={data.carryoverAmount} />],
            ['예산총액', <Num value={data.totalBudgetAmount} />],
            ['집행액', <Num value={data.executedAmount} />],
            ['예산잔액', <Num value={data.budgetBalance} />],
          ]}
        />
      )}
    </Drawer>
  );
}

export default function FnSfr02402Page({ role }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetItemId, setBudgetItemId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/purchase-requests/budget-status', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );

  const rows = data ? data.items : [];
  const shortage = rows.filter((r) => Number(r.budgetBalance) < 0);
  const sum = (key: string) => rows.reduce((acc, r) => acc + Number(r[key] || 0), 0);

  const search = () => {
    setPage(0);
    setApplied({ projectId, budgetItemId, title });
  };
  const reset = () => {
    setProjectId('');
    setBudgetItemId('');
    setTitle('');
    setPage(0);
    setApplied({});
  };

  const columns = [
    { key: 'purchaseRequestId', label: '품의서 ID' },
    { key: 'title', label: '품의 제목' },
    { key: 'execBudgetAmount', label: '실행예산액', render: (r: Row) => <Num value={r.execBudgetAmount} /> },
    { key: 'carryoverAmount', label: '이월 대상 금액', render: (r: Row) => <Num value={r.carryoverAmount} /> },
    { key: 'totalBudgetAmount', label: '예산총액', render: (r: Row) => <Num value={r.totalBudgetAmount} /> },
    { key: 'executedAmount', label: '집행액', render: (r: Row) => <Num value={r.executedAmount} /> },
    { key: 'budgetBalance', label: '예산잔액', render: (r: Row) => <Num value={r.budgetBalance} /> },
  ];

  return (
    <div className={'bento'}>
      <section className={'box span-12'}>
        <h2>현재 쪽 합계</h2>
        <Tiles
          items={[
            ['예산총액', <Num value={sum('totalBudgetAmount')} />],
            ['집행액', <Num value={sum('executedAmount')} />],
            ['예산잔액', <Num value={sum('budgetBalance')} />],
          ]}
        />
      </section>
      <section className={'box span-8'}>
        <h2>품의서별 예산</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label={'프로젝트'}>
            <LookupSelect table={'project'} role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label={'예산과목'}>
            <LookupSelect table={'budget_item'} role={role} value={budgetItemId} onChange={setBudgetItemId} />
          </Field>
          <Field label={'품의 제목'}>
            <TextInput value={title} onChange={setTitle} />
          </Field>
        </Filters>
        {error && <ErrorText text={error} />}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => setSelected(Number(r.purchaseRequestId))}
          empty={loading ? '불러오는 중…' : '조회 결과가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className={'box span-4'}>
        <h2>잔액 부족</h2>
        <Band total={shortage.length} />
        <DataTable
          columns={[
            { key: 'title', label: '품의 제목' },
            { key: 'budgetBalance', label: '예산잔액', render: (r: Row) => <Num value={r.budgetBalance} /> },
          ]}
          rows={shortage}
          onRowClick={(r) => setSelected(Number(r.purchaseRequestId))}
          empty={'잔액이 부족한 품의서가 없습니다.'}
        />
      </section>
      {selected !== null && <Detail id={selected} role={role} onClose={() => setSelected(null)} />}
    </div>
  );
}
